/****** Object:  StoredProcedure `get_balanceentry`    Script Date: 7/30/2026 1:04:14 PM ******/
-- DELIMITER $$
-- CREATE PROCEDURE `get_balanceentry`(
--     IN `StartDate` VARCHAR(50),
--     IN `EndDate` VARCHAR(50)
-- )
-- BEGIN
--     SELECT `CustomerId`, `Description`,
--            SUM(`Credit`) AS `Credit`,
--            SUM(`Debit`) AS `Debit`,
--            SUM(`Credit`) - SUM(`Debit`) AS `Balance`
--     FROM `tbl_Transaction`
--     WHERE STR_TO_DATE(`Date`, '%m/%d/%Y')
--           BETWEEN STR_TO_DATE(`StartDate`, '%m/%d/%Y') AND STR_TO_DATE(`EndDate`, '%m/%d/%Y')
--     GROUP BY `CustomerId`, `Description`;
-- END$$
-- DELIMITER ;

SET FOREIGN_KEY_CHECKS = 1;
